document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("frequency-form"),t=document.getElementById("frequency-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("freq-t").value),o=parseFloat(document.getElementById("freq-f").value);!isNaN(n)&&n>0&&(isNaN(o)||0===o)?t.innerHTML=`<b>Frequency (f):</b> ${(1/n).toFixed(4)} Hz`:!isNaN(o)&&o>0&&(isNaN(n)||0===n)?t.innerHTML=`<b>Period (T):</b> ${(1/o).toFixed(4)} s`:t.textContent="Enter either period or frequency (only one value)!"})});